#include "include/Graph.h"
#include "include/RouteManager.h"
#include <iostream>
#include <limits>
using namespace std;
static void buildCity(Graph& g){const char* n[]={"Restaurant A","Restaurant B","Sector 62 Crossing","Sector 63 Crossing","Electronic City","Main Road Junction","Market Crossing","Residential Area A","Residential Area B","Hospital Junction","Metro Station","Shopping Complex","Customer A","Customer B","Customer C","Industrial Outpost"};for(const char* x:n)g.addVertex(x);int roads[][3]={{0,2,4},{0,5,7},{1,3,3},{1,6,6},{2,3,2},{2,4,6},{2,5,3},{3,6,4},{4,5,2},{4,10,5},{5,6,3},{5,9,5},{6,7,4},{6,11,3},{7,8,2},{7,12,5},{8,9,3},{8,13,4},{9,10,2},{9,14,7},{10,11,2},{11,12,3},{11,13,5},{12,14,4}};for(const auto& r:roads)g.addEdge(r[0],r[1],r[2]);}
static bool readId(const char* prompt,int& x){cout<<prompt;if(cin>>x)return true;cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');return false;}
int main(){Graph city;buildCity(city);RouteManager routes(city);int choice=-1;while(choice){cout<<"\n========================================\n       FOOD DELIVERY ROUTING SYSTEM\n========================================\n1. Display City Map\n2. Find Shortest Route\n3. Update Traffic\n4. Close Road\n5. Reopen Road\n6. Calculate Rider-to-Restaurant Route\n7. Calculate Restaurant-to-Customer Route\n0. Exit\nChoice: ";if(!(cin>>choice)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');continue;}int a,b;double t;if(choice==1)city.displayGraph();else if(choice==2||choice==6||choice==7){if(readId("Source ID: ",a)&&readId("Destination ID: ",b))routes.printPath(routes.shortestPath(a,b),cout);}else if(choice==3){if(readId("From ID: ",a)&&readId("To ID: ",b)){cout<<"New travel time: ";if(cin>>t)cout<<(city.updateTraffic(a,b,t)?"Traffic updated.\n":"Invalid road or travel time.\n");}}else if(choice==4||choice==5){if(readId("From ID: ",a)&&readId("To ID: ",b))cout<<((choice==4?city.closeRoad(a,b):city.reopenRoad(a,b))?"Road status updated.\n":"Invalid road.\n");}else if(choice!=0)cout<<"Invalid option.\n";}return 0;}
